x</mi><mo>+</mo><mn>10</mn></mrow></mfenced><mo>=</mo><mn>0</mn></math>, or <math alttext=\"left parenthesis x plus 10 right parenthesis squared equals 0\"><msup><mfenced><mrow><mi>x</mi><mo>+</mo><mn>10</mn></mrow></mfenced><mn>2</mn></msup><mo>=</mo><mn>0</mn></math>. Taking the square root of both sides of this equation yields <math alttext=\"x plus 10 equals 0\"><mrow>\n\t<mrow>\n\t\t<mi>x</mi>\n\t\t<mo>+</mo>\n\t\t<mn>10</mn>\n\t</mrow>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math>. Subtracting <math alttext=\"10\"><mn>10</mn>\n</math> from both sides of this equation yields <math alttext=\"x equals negative 10\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mo>-</mo><mn>10</mn>\n</mrow>\n</math>. Therefore, the value of <math alttext=\"x\"><mi>x</mi>\n</math> is <math alttext=\"negative 10\"><mo>-</mo><mn>10</mn>\n</math>.</p>","origin":"manifold","stem":"<p style=\"text-align: center;\"><math alttext=\"x squared plus y plus 7 equals 7\"><mrow>\n\t<mrow>\n\t\t<msup>\n\t\t\t<mi>x</mi>\n\t\t\t<mn>2</mn>\n\t\t</msup>\n\t\t<mo>+</mo>\n\t\t<mi>y</mi>\n\t\t<mo>+</mo>\n\t\t<mn>7</mn>\n\t</mrow>\n\t<mo>=</mo>\n\t<mn>7</mn>\n</mrow>\n</math></p>\n<p style=\"text-align: center;\"><math alttext=\"20 x plus 100 minus y equals 0\"><mrow><mn>20</mn></mrow><mi>x</mi><mo>+</mo><mrow><mn>100</mn></mrow><mo>-</mo><mi>y</mi><mo>=</mo><mn>0</mn></math></p>\n<p style=\"text-align: left;\">The solution to the given system of equations is&nbsp;<math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math>. What is the value of <math alttext=\"x\"><mi>x</mi>\n</math>?</p>","externalid":"7e4cd51c-5329-4e8b-83dd-1416f04a294f","templateid":"c3657fac-8535-4040-aefc-12767f170702","vaultid":"11fad1ef-6f66-4959-b400-457b4f7204f0","type":"spr","answerOptions":[],"correct_answer":["-10"]},"createDate":1691007959823,"updateDate":1691007959823}$SATQ$::jsonb, 1691007959823, 1691007959823),
    ($SATQ$58dcc59f$SATQ$, NULL, NULL, $SATQ$06375-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$spr$SATQ$, NULL, $SATQ$<p class="stem_paragraph ">A landscaper is designing a rectangular garden. The length of the garden is to be 5 feet longer than the width. If the area of the garden will be 104&nbsp;square feet, what will be the length, in feet, of the garden?</p>
$SATQ$, NULL, $SATQ$["13"]$SATQ$::jsonb, NULL, $SATQ$<p>The correct answer is 13. Let <span class="italic">w</span> represent the width of the rectangular garden, in feet. Since the length of the garden will be 5 feet longer than the width of the garden, the length of the garden will be <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_000_3112a989.png" alt="w plus 5"></span> feet. Thus the area of the garden will be <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_001_dc07eaae.png" alt="w times, open parenthesis, w plus 5, close parenthesis"></span>. It is also given that the area of the garden will be 104 square feet. Therefore, <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_002_e0862630.png" alt="w times, open parenthesis, w plus 5, close parenthesis, equals 104"></span>, which is equivalent to <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_003_1d527031.png" alt="w squared, plus 5 w, minus 104, equals 0"></span>. Factoring this equation results in <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_004_225c615f.png" alt="open parenthesis, w plus 13, close parenthesis, times, open parenthesis, w minus 8, close parenthesis, equals 0"></span>. Therefore, <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_005_97ba3f55.png" alt="w equals 8"></span> and <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_006_eca1ffcc.png" alt="w equals negative 13"></span>. Because width cannot be negative, the width of the garden must be 8 feet. This means the length of the garden must be <span class="math-container"><img align="middle" role="math" class="math-img" src="https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_007_b0471d9a.png" alt="8 plus 5, equals 13"></span> feet.</p>
$SATQ$, true, 8, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ$SPR$SATQ$, $SATQ$Math$SATQ$, $SATQ${"questionId":"58dcc59f","external_id":null,"disclosed_item_id":"06375-DC","source":"disclosed","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"P","domain":"Advanced Math","skill_cd":"P.C.","skill_desc":"Nonlinear functions","difficulty":"H","score_band_range_cd":6,"type":"spr","stimulus":null,"stem":"<p class=\"stem_paragraph \">A landscaper is designing a rectangular garden. The length of the garden is to be 5 feet longer than the width. If the area of the garden will be 104&nbsp;square feet, what will be the length, in feet, of the garden?</p>\n","answerOptions":null,"keys":null,"correct_answer":["13"],"rationale":"<p>The correct answer is 13. Let <span class=\"italic\">w</span> represent the width of the rectangular garden, in feet. Since the length of the garden will be 5 feet longer than the width of the garden, the length of the garden will be <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_000_3112a989.png\" alt=\"w plus 5\"></span> feet. Thus the area of the garden will be <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_001_dc07eaae.png\" alt=\"w times, open parenthesis, w plus 5, close parenthesis\"></span>. It is also given that the area of the garden will be 104 square feet. Therefore, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/58dcc59f/img_002_e0862630.png\" alt=\"w times, open parenthesis, w plus 5, close parenthesis, equals 104\"></span>, which is equivalent to <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" s