-120\"></path>\n</defs>\n<g transform=\"translate(334.437387 223.24334)scale(0.2 -0.2)\">\n<use xlink:href=\"#CrimsonText-Italic-120\"></use>\n</g>\n</g>\n</g>\n<g id=\"line2d_1\">\n<defs>\n<path d=\"M 0 3 \nC 0.795609 3 1.55874 2.683901 2.12132 2.12132 \nC 2.683901 1.55874 3 0.795609 3 0 \nC 3 -0.795609 2.683901 -1.55874 2.12132 -2.12132 \nC 1.55874 -2.683901 0.795609 -3 0 -3 \nC -0.795609 -3 -1.55874 -2.683901 -2.12132 -2.12132 \nC -2.683901 -1.55874 -3 -0.795609 -3 0 \nC -3 0.795609 -2.683901 1.55874 -2.12132 2.12132 \nC -1.55874 2.683901 -0.795609 3 0 3 \nz\n\" id=\"m72a75a6d15\" style=\"stroke:#000000;\"></path>\n</defs>\n<g clip-path=\"url(#p0a4a18b084)\">\n<use style=\"stroke:#000000;\" x=\"168.190088\" xlink:href=\"#m72a75a6d15\" y=\"106.939694\"></use>\n</g>\n</g>\n<g id=\"line2d_2\">\n<path clip-path=\"url(#p0a4a18b084)\" d=\"M 111.076421 44.193917 \nL 317.403282 270.867143 \nL 317.403282 270.867143 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n</g>\n<g id=\"line2d_3\">\n<path clip-path=\"url(#p0a4a18b084)\" d=\"M 143.595329 46.182822 \nL 145.838012 56.009197 \nL 148.080695 64.619612 \nL 150.323378 72.164534 \nL 152.566062 78.775813 \nL 154.808745 84.568981 \nL 157.051428 89.645277 \nL 159.294112 94.093408 \nL 161.536795 97.991107 \nL 163.779478 101.406487 \nL 166.022161 104.399233 \nL 168.264845 107.021642 \nL 170.507528 109.319542 \nL 172.750211 111.333089 \nL 174.992894 113.097471 \nL 177.796249 114.999161 \nL 180.599603 116.611395 \nL 183.402957 117.978231 \nL 186.766982 119.346691 \nL 190.131007 120.469169 \nL 194.055702 121.526366 \nL 198.541069 122.470158 \nL 203.587106 123.272675 \nL 209.193814 123.924805 \nL 215.921864 124.47008 \nL 224.331926 124.908104 \nL 234.984672 125.226532 \nL 250.122784 125.44178 \nL 276.474313 125.559667 \nL 317.403282 125.588501 \nL 317.403282 125.588501 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n</g>\n</g>\n</g>\n<defs>\n<clipPath id=\"p0a4a18b084\">\n<rect height=\"347.76\" width=\"339.296814\" x=\"15.211593\" y=\"7.2\"></rect>\n</clipPath>\n</defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for graph of a system of a line and a curve\" class=\"sr-only\"><ul><li>For the line in the system:<br>\n<ul>\n<li>The line slants sharply down from left to right.</li>\n<li>The line passes through the following points:<br>\n<ul>\n<li>(negative 2 comma 6)</li>\n<li>approximately (0 comma 3.8)</li>\n</ul>\n</li>\n</ul>\n</li>\n<li>For the curve in the system:<br>\n<ul>\n<li>Moving from left to right:\n<ul>\n<li>The curve passes from quadrant 2 to quadrant 1.</li>\n<li>In quadrant 2:<br>\n<ul>\n<li>The curve trends down sharply to the point (negative 2 comma 6).</li>\n<li>The curve then trends down gradually to the y axis.</li>\n</ul>\n</li>\n<li>In quadrant 1, the curve trends down gradually.</li>\n</ul>\n</li>\n<li>As x increases, the curve approaches the line y equals 5.</li>\n<li>The curve passes through the following points:<br>\n<ul>\n<li>(negative 3 comma 8)</li>\n<li>(negative 2 comma 6)</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">The graph of a system of a linear equation and a nonlinear equation is shown. What is the solution <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> to this system?</p>","answerOptions":[{"id":"d32a59d9-1caf-4b9a-b68d-1465eeea67cf","content":"<p><math alttext=\"left parenthesis 6 comma 0 right parenthesis\"><mfenced><mrow><mrow><mn>6</mn></mrow><mo>,</mo><mn>0</mn></mrow></mfenced></math></p>"},{"id":"7b52ae01-5997-48f4-87c3-93055ad408f7","content":"<p><math alttext=\"left parenthesis negative 2 comma 6 right parenthesis\"><mfenced><mrow><mrow><mo>-</mo><mn>2</mn></mrow><mo>,</mo><mrow><mn>6</mn></mrow></mrow></mfenced></math></p>"},{"id":"98310b2e-8919-4bd0-a2ca-c1dd7b54f627","content":"<p><math alttext=\"left parenthesis 0 comma negative 2 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mrow><mo>-</mo><mn>2</mn></mrow></mrow></mfenced></math></p>"},{"id":"20f97abf-bf66-45a0-9b3f-69695bb860b1","content":"<p><math alttext=\"left parenthesis 0 comma 0 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>0</mn></mrow></mfenced></math></p>"}],"keys":["7b52ae01-5997-48f4-87c3-93055ad408f7"],"correct_answer":["B"],"rationale":"<p style=\"text-align: left;\">Choice B is correct. The solution <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math> to the system of two equations corresponds to the point where the graphs of the equations intersect in the <em>xy</em>-plane. The graphs of the linear equation and the nonlinear equation shown intersect at the point <math alttext=\"left parenthesis negative 2 comma 6 right parenthesis\"><mfenced><mrow><mo>-</mo><mn>2</mn><mo>,</mo><mn>6</mn></mrow></mfenced></math>. Thus, the solution <math alttext=\"left parenthesis x comma y right parenthesis\"><mfenced><mrow><mi>x</mi><mo>,</mo><mi>y</mi></mrow></mfenced></math>&nbsp;to this system is <math alttext=\"left parenthesis negative 2 comma 6 right parenthesis\"><mfenced><mrow><mo>-</mo><mn>2</mn><mo>,</mo><mn>6</mn></mrow></mfenced></math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice C is incorrect and may result from conceptual or calculation errors.</p>\n<p style=\"text-align: left;\">Choice D is incorrect and may result from conceptual or calculation errors.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1730147357396,"pPcc":"SAT#P","questionId":"5c7d5744","skill_cd":"P.B.","score_band_range_cd":1,"skill_desc":"Nonlinear equations in one variable and systems of equations in tw